#!/usr/bin/env bash
# Propose a regenerated contributors.svg as a pull request into master.
# Run after contributors-svg.sh has rewritten the file in the checkout.
#
# Never force-pushes: every proposal gets a new bot/contributors-<run id>
# branch. Open proposals from earlier runs are left alone when they already
# carry the same file, and closed (branch deleted) once they are superseded
# or master has caught up.
#
# Env: GH_TOKEN, GITHUB_REPOSITORY, GITHUB_SHA, GITHUB_RUN_ID (all set in
# Actions; GH_TOKEN from secrets.GITHUB_TOKEN).
set -euo pipefail

file=contributors.svg
base=master
prefix=bot/contributors-

# Open PRs this workflow opened earlier: "number<TAB>branch" per line.
open_prs() {
  gh pr list --base "$base" --state open --author "app/github-actions" \
    --json number,headRefName,isCrossRepository \
    --jq ".[] | select(.isCrossRepository | not)
             | select(.headRefName | startswith(\"${prefix}\"))
             | [.number, .headRefName] | @tsv"
}

close_prs() {  # $1 = comment; skips PR number $2 if given
  local number branch
  while IFS=$'\t' read -r number branch; do
    [[ -n "$number" && "$number" != "${2:-}" ]] || continue
    echo "Closing #${number} (${branch})"
    gh pr close "$number" --delete-branch --comment "$1"
  done < <(open_prs)
}

if git diff --quiet -- "$file"; then
  echo "${file} on ${base} is up to date."
  close_prs "Closing: ${file} on ${base} is already up to date."
  exit 0
fi

# Same content already proposed? GitHub's contents API returns the git blob
# SHA, which hash-object computes locally.
blob="$(git hash-object "$file")"
while IFS=$'\t' read -r number branch; do
  [[ -n "$number" ]] || continue
  theirs="$(gh api "repos/${GITHUB_REPOSITORY}/contents/${file}?ref=${branch}" --jq .sha)"
  if [[ "$theirs" == "$blob" ]]; then
    echo "#${number} already proposes this ${file}; nothing to do."
    exit 0
  fi
done < <(open_prs)

branch="${prefix}${GITHUB_RUN_ID}"
git config user.name "github-actions[bot]"
git config user.email "41898283+github-actions[bot]@users.noreply.github.com"
git switch -c "$branch"
git add "$file"
git commit -m "chore: update contributors"
git push origin "$branch"

url="$(gh pr create --base "$base" --head "$branch" \
  --title "Update contributors" \
  --body "Regenerated by the Contributors workflow from the commit history at ${GITHUB_SHA}.")"
echo "Opened ${url}"
close_prs "Superseded by ${url}." "${url##*/}"
